"use client";

import { useState } from "react";
import dynamic from "next/dynamic";
import type { SourceCount } from "@/lib/types";

// recharts only after "Показати графік". ssr: false is allowed here: this is a Client Component
// (in a Server Component it fails the build, see node_modules/next/dist/docs/01-app/02-guides/lazy-loading.md).
const SourcesChart = dynamic(() => import("./sources-chart").then((m) => m.SourcesChart), {
  ssr: false,
  loading: () => <div className="h-64 w-full" />,
});

type ExportRow = {
  id: string;
  fullName: string;
  company: string;
  email: string;
  phone: string;
  status: string;
  source: string;
  createdAt: string;
};

export function LeadsToolbar({ sources }: { sources: SourceCount[] }) {
  const [showChart, setShowChart] = useState(false);
  const [exporting, setExporting] = useState(false);

  async function handleExport() {
    setExporting(true);
    try {
      const response = await fetch("/api/leads");
      const { leads } = (await response.json()) as { leads: ExportRow[] };
      // exceljs is ~1 MB: load it on the first export click, not with the dashboard.
      const { default: ExcelJS } = await import("exceljs");

      const workbook = new ExcelJS.Workbook();
      const sheet = workbook.addWorksheet("Leads");
      sheet.columns = [
        { header: "ID", key: "id", width: 12 },
        { header: "Контакт", key: "fullName", width: 28 },
        { header: "Компанія", key: "company", width: 24 },
        { header: "Email", key: "email", width: 34 },
        { header: "Телефон", key: "phone", width: 18 },
        { header: "Статус", key: "status", width: 14 },
        { header: "Джерело", key: "source", width: 16 },
        { header: "Створено", key: "createdAt", width: 22 },
      ];
      sheet.addRows(leads);
      sheet.getRow(1).font = { bold: true };

      const buffer = await workbook.xlsx.writeBuffer();
      const blob = new Blob([buffer], {
        type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `leads-${new Date().toISOString().slice(0, 10)}.xlsx`;
      link.click();
      URL.revokeObjectURL(url);
    } finally {
      setExporting(false);
    }
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap gap-2">
        <button
          type="button"
          onClick={handleExport}
          disabled={exporting}
          className="rounded-md border border-slate-300 bg-white px-3 py-1.5 text-sm hover:bg-slate-50 disabled:opacity-60"
        >
          {exporting ? "Готуємо файл…" : "Експорт в Excel"}
        </button>
        <button
          type="button"
          onClick={() => setShowChart(!showChart)}
          className="rounded-md border border-slate-300 bg-white px-3 py-1.5 text-sm hover:bg-slate-50"
        >
          {showChart ? "Сховати графік" : "Показати графік джерел"}
        </button>
      </div>
      {showChart && (
        <div className="rounded-lg border border-slate-200 bg-white p-4">
          <SourcesChart data={sources} />
        </div>
      )}
    </div>
  );
}

import { logout } from "@/app/login/actions";
import { getCurrentUser, getWorkspace } from "@/lib/data";

export async function DashboardHeader() {
  const user = await getCurrentUser();
  const workspace = await getWorkspace(user.workspaceSlug);

  return (
    <header className="flex items-center justify-between border-b border-slate-200 bg-white px-6 py-3">
      <div>
        <p className="text-sm font-medium">{workspace.name}</p>
        <p className="text-xs text-slate-500">{workspace.timezone}</p>
